import { Suspense } from 'react'
import { CardStats } from './CardStats'
import { LatestInvoices } from './LatestInvoices'
import { RevenueChart } from './RevenueChart'
import {
  CardStatsSkeleton,
  RevenueChartSkeleton,
  LatestInvoicesSkeleton,
  DashboardShell,
} from './skeletons'

// Separate data fetching for each component enables independent streaming
async function getCardStats() {
  const res = await fetch('https://api.example.com/stats', {
    next: { revalidate: 60 },
  })
  return res.json()
}

async function getRevenueData() {
  const res = await fetch('https://api.example.com/revenue', {
    next: { revalidate: 300 },
  })
  return res.json()
}

async function getLatestInvoices() {
  const res = await fetch('https://api.example.com/invoices', {
    next: { revalidate: 60 },
  })
  return res.json()
}

// Async wrapper components for Suspense boundaries
async function CardStatsWrapper() {
  const data = await getCardStats()
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartWrapper() {
  const data = await getRevenueData()
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesWrapper() {
  const data = await getLatestInvoices()
  return <LatestInvoices invoices={data.invoices} />
}

export default function Page() {
  return (
    <DashboardShell>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStatsWrapper />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChartWrapper />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoicesWrapper />
      </Suspense>
    </DashboardShell>
  )
}

