import {
  CardStatsSkeleton,
  RevenueChartSkeleton,
  LatestInvoicesSkeleton,
  DashboardShell,
} from './skeletons'

// Loading UI shown immediately while PPR streams in content
// This matches the DashboardShell structure for smooth transition
export default function Loading() {
  return (
    <DashboardShell>
      <CardStatsSkeleton />
      <RevenueChartSkeleton />
      <LatestInvoicesSkeleton />
    </DashboardShell>
  )
}

import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Create Next App',
  description: 'Generated by create next app',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <head>
        <style>{`
          /* Skeleton animation styles */
          @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.4; }
          }

          .skeleton-pulse > * {
            animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
            background: linear-gradient(90deg, #e2e8f0 25%, #cbd5e1 50%, #e2e8f0 75%);
            background-size: 200% 100%;
            border-radius: 4px;
          }

          .skeleton-text-sm {
            height: 16px;
            width: 60%;
            margin-bottom: 8px;
          }

          .skeleton-text-md {
            height: 20px;
            width: 40%;
            margin-bottom: 12px;
          }

          .skeleton-text-lg {
            height: 32px;
            width: 80%;
          }

          .skeleton-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
          }

          .skeleton-item {
            height: 24px;
            width: 100%;
          }

          .skeleton-row {
            height: 20px;
            width: 100%;
          }

          /* Dashboard layout */
          .dashboard {
            max-width: 1200px;
            margin: 0 auto;
            padding: 24px;
          }

          .dashboard h1 {
            font-size: 2rem;
            font-weight: 600;
            margin-bottom: 24px;
            color: #1e293b;
          }

          .grid {
            display: grid;
            gap: 16px;
          }

          .grid-cols-2 {
            grid-template-columns: repeat(2, 1fr);
          }

          .card {
            background: white;
            border: 1px solid #e2e8f0;
            border-radius: 8px;
            padding: 16px;
          }

          .card h2 {
            font-size: 0.875rem;
            color: #64748b;
            margin: 0 0 8px 0;
          }

          .card p {
            font-size: 1.5rem;
            font-weight: 600;
            color: #1e293b;
            margin: 0;
          }

          .chart, .invoices {
            background: white;
            border: 1px solid #e2e8f0;
            border-radius: 8px;
            padding: 16px;
            margin-top: 16px;
          }

          .chart h2, .invoices h2 {
            font-size: 1.125rem;
            font-weight: 600;
            color: #1e293b;
            margin: 0 0 16px 0;
          }

          .chart ul, .invoices ul {
            list-style: none;
            padding: 0;
            margin: 0;
          }

          .chart li, .invoices li {
            padding: 8px 0;
            border-bottom: 1px solid #e2e8f0;
            color: #475569;
          }

          .chart li:last-child, .invoices li:last-child {
            border-bottom: none;
          }
        `}</style>
      </head>
      <body style={{ margin: 0, fontFamily: 'system-ui, -apple-system, sans-serif', background: '#f8fafc' }}>
        {children}
      </body>
    </html>
  )
}

